package com.optarena.app

data class Invoice(
    val id: Int,
    val lines: MutableList<Double>,
    val discount: Double = 0.0,
)

object Billing {
    // Return a NEW invoice with the discount applied to every line.
    // The original invoice must not change.
    //
    // BUG: data-class copy() is SHALLOW - the copy shares the same
    // MutableList, so mutating the copy's lines corrupts the original.
    fun withDiscount(invoice: Invoice, discount: Double): Invoice {
        val discounted = invoice.copy(discount = discount)
        for (i in discounted.lines.indices) {
            discounted.lines[i] = discounted.lines[i] * (1 - discount)
        }
        return discounted
    }

    fun total(invoice: Invoice): Double =
        invoice.lines.sum()
}

