package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class BillingHiddenTest {

    @Test
    fun discountAppliedToCopy() {
        val original = Invoice(1, mutableListOf(100.0, 50.0))
        val discounted = Billing.withDiscount(original, 0.1)
        assertEquals(135.0, Billing.total(discounted), 1e-9)
        assertEquals(0.1, discounted.discount, 1e-9)
    }

    @Test
    fun originalIsUntouched() {
        val original = Invoice(2, mutableListOf(100.0, 50.0))
        Billing.withDiscount(original, 0.5)
        assertEquals(150.0, Billing.total(original), 1e-9)
        assertEquals(listOf(100.0, 50.0), original.lines)
    }
}

